head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.bbsTypeCd = "7";
scwin.contnId;
scwin.gRegEmpNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        tbox_mkt_tp.hide();
        $c.elw.fn_searchCode("LIST_INVSTG_FAQ_CLSS_CD");
        const parentYn = $c.frame.path("../").scwin.contnId;
        if (parentYn === null || parentYn === "undefined" || parentYn.length === 0) {
            scwin.contnId = "input";
        } else {
            getContnId = $c.frame.path("../").fn_getContnId;
            scwin.contnId = getContnId();
        }
        if (scwin.contnId !== "input") {
            await scwin.read();
        } else {
            scwin.setFileDataHeader();
            await scwin.setSaveHeader();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06008.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

