 * @name dts_ContentsInfo_OnLoadCompleted
 * @description dts_ContentsInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ContentsInfo_OnLoadCompleted = function(rowcount) {
    try {
        scwin.gRegEmpNo = dts_ContentsInfo.getCellData(0, "WRTR_ID");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06008.dts_ContentsInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_fileList_OnDblClick
 * @description grd_fileList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_OnDblClick = function(row, colid) {
    try {
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0 && dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename") !== "" && dts_fileList.getCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ") !== "") {
            $c.elw.fn_filedown(dts_fileList.getCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06008.grd_fileList_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        if (scwin.contnId === "input") {
            await scwin.save();
        } else {
            await scwin.update();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06008.btn_save_onclick" });
    }
};

