 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (tbox_title.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_title, 100, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_contn_contn.Text === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_contn_contn.focus();
        return;
    }
    if (!await scwin.checkMaxLength2(tarea_contn_contn, 2000, "내용")) {
        tarea_contn_contn.text = "";
        tarea_contn_contn.focus();
        return false;
    }
    let rtn = confirm('수정 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_ContentsInfo.setCellData(1, "ANS_OBJ_CONTN_ID", "0");
        dts_ContentsInfo.setCellData(1, "LIST_INVSTG_BBS_TP_CD", scwin.bbsTypeCd);
        dts_ContentsInfo.setCellData(1, "QUES_BZ_TP_CD", "");
        dts_ContentsInfo.setCellData(1, "WRTR_ID", js_emp_no);
        dts_ContentsInfo.setCellData(1, "ISUR_CD", js_dep_cd);
        dts_ContentsInfo.setCellData(1, "REG_TEL_NO", "");
        dts_ContentsInfo.setCellData(1, "WRTR_EMAIL", js_email);
        dts_ContentsInfo.setCellData(1, "QUES_ANS_TP_CD", "");
        dts_ContentsInfo.setCellData(1, "LD_MKT_TP_CD", js_market);
        dts_ContentsInfo.setCellData(1, "LIST_TP_CLSS_CD", "");
        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/lstinvstg/ListCommBoard.do",
            ref : "dts_ContentsInfo,dts_fileList",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    let rtn = confirm('삭제 하시겠습니까?');
    if (rtn === 1) {

        // dts_ContentsDel.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_ContentsDel.insertRow();
        dts_ContentsDel.setCellData(1, "CONTN_ID", scwin.contnId);
        // [전환검토] trs_Delete.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     CONTN_ID : scwin.contnId
        // };
        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/lstinvstg/ListCommBoard.do",
            ref : "dts_ContentsDel",
            target : "trs_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

